import { lesson as L, question as Q } from './helpers.mjs';

export const beginnerLessons = [
  L({
    id: 'what-is-crm', title: 'What is a CRM, really?', minutes: 10,
    objective: 'Understand what a CRM does, using a business you can picture.',
    prerequisite: 'Nothing at all. This is your starting point.', diagram: 'crm',
    explanation: [
      'CRM stands for customer relationship management. Think of it as a shared, organized notebook about the people your business helps. It stores contact details, conversations, and next steps so the team does not have to remember everything or search through different spreadsheets.',
      'HubSpot is a customer platform built around a CRM. A contact is a person. A company is a business. A deal is a possible sale. A ticket is a request for help. Keeping those things separate makes the information easier to use. A person can exist in your CRM without being a customer or agreeing to receive marketing emails.',
      'A CRM works best when someone owns the next step and the information is correct. It does not automatically give you a good sales process or permission to contact people. Start with one useful question: who is this person, what do they need, and what should happen next?',
    ],
    example: 'BrightPath Workshops teaches small creative teams. Maya asks about a design workshop. Her name and email belong on a contact record. Cedar Studio, her workplace, is a company. A possible team booking is a deal. A question about joining instructions later becomes a ticket. The team can connect these records without mixing them into one long note.',
    steps: ['Draw four boxes called Contact, Company, Deal, and Ticket on paper or in your notes.', 'Write Maya Patel under Contact and Cedar Studio under Company.', 'Write Team design workshop under Deal. This is only a possible sale, not money already received.', 'Write Cannot find joining instructions under Ticket.', 'Explain aloud which box you would open to find Maya\'s email, then which one you would open to track a possible sale.'],
    outcome: 'You can explain the four record types without using technical language: person, business, possible sale, and request for help.',
    pitfalls: ['A contact is not automatically a customer or a marketing subscriber.', 'Do not store every piece of information in a single notes field. Use the correct kind of record.'],
    advanced: 'HubSpot calls a kind of record an object. A particular contact, such as Maya, is one record of the contact object. A record can be connected to other records using associations.',
    recap: ['CRM is a shared customer notebook.', 'Keep people, businesses, possible sales, and support requests distinct.', 'Good data and clear next steps matter more than adding lots of fields.'],
    sources: ['objects', 'products'],
    quiz: [Q('Maya asks about a workshop. Where does her personal email belong?', ['A contact record', 'A deal amount', 'A support pipeline'], 0, 'A contact represents a person and holds details such as their email. A deal amount is a possible sale value. A support pipeline organizes tickets, not personal details.'), Q('A person appears in your CRM. What can you safely conclude?', ['They have agreed to all marketing emails', 'Your team has a record for that person', 'They have already paid'], 1, 'Being in the CRM means a record exists. It does not prove marketing permission or a completed purchase. Those are separate facts that need evidence.')],
  }),
  L({
    id: 'hubspot-hubs', title: 'How the HubSpot pieces fit together', minutes: 11, diagram: 'journey',
    objective: 'Know which tool family helps with which job, without memorizing every feature.',
    explanation: ['Smart CRM is the shared foundation. The hubs are groups of tools built around different business jobs. Marketing Hub helps attract and nurture interest. Sales Hub helps salespeople organize and follow up on opportunities. Service Hub helps teams support customers.', 'Content Hub helps create and manage content such as website pages. Data Hub helps organize, connect, and improve data; older tutorials may say Operations Hub. Revenue Hub covers revenue processes such as quotes, billing, and payments; older material may say Commerce Hub. Product names and packaging change, so use the current product catalog.', 'A subscription is the plan an account buys. A seat is a type of access assigned to a user. A permission controls which actions that user can perform. Some features also use credits. Having a paid account does not automatically mean every person can use every feature. You can learn all the ideas here without buying anything.'],
    example: 'BrightPath uses one contact record for Maya. Marketing sees her workshop interest, sales sees the team-training conversation, and service sees her support request. They are not three unrelated people just because three teams use different tools.',
    steps: ['Write your goal first: for example, organize contacts, draft a newsletter, or follow up on a possible sale.', 'Match each goal to the hub that normally supports it: CRM, Marketing, or Sales.', 'Open the official products reference below and compare the descriptions with your list.', 'Use the product catalog when you need to confirm availability. Do not assume an old tutorial\'s plan names or limits still apply.', 'For this course, start with CRM and marketing. Keep the other hubs as a map, not a shopping list.'],
    outcome: 'You can choose the right family of tools for a business task and know to check plan, seat, and permission requirements.',
    pitfalls: ['Do not buy a plan just to finish a simulation on this site.', 'A hub name is not the same thing as a user permission.'],
    advanced: 'Different hubs share CRM objects, but their workflows and actions can have different subscription requirements. A workflow editor being available does not mean its marketing email action is available.',
    recap: ['Start with the job, then choose the tool.', 'CRM connects the teams.', 'Check live packaging instead of memorizing prices or quotas.'], sources: ['products', 'catalog', 'workflows'],
    quiz: [Q('Which question should come before choosing a hub?', ['Which plan has the most buttons?', 'What business job do we need to do?', 'Which color looks best?'], 1, 'Begin with the job, such as handling support requests. That makes the relevant tools clearer. Button counts and colors do not tell you whether a product fits your process.'), Q('A feature is locked for one user. What should you check?', ['Only their browser theme', 'Whether they completed this course', 'The plan, assigned seat, and permissions'], 2, 'Access depends on product packaging and user access, and sometimes credits or region. This course does not unlock HubSpot features, and a browser theme does not grant access.')],
  }),
  L({
    id: 'customer-journey', title: 'Follow one person, not a pile of tools', minutes: 12, diagram: 'journey',
    objective: 'Turn a simple customer journey into a useful plan for your team.',
    explanation: ['A customer journey is the set of steps a person takes while discovering, considering, buying, and using something. It is not always a straight line. Someone might visit your website several times, ask a question, and leave before returning later.', 'Inbound thinking starts by being useful: attract the right people, help them understand their options, and support them after they buy. Do not start by asking how many emails you can send. Start by asking what someone needs at each step. A good experience continues after a deal is won.', 'A journey map is a teaching and planning tool. It is not a HubSpot property and does not automatically change a record. Later, you will use lifecycle stages, deal stages, activities, and tickets to represent specific parts of that journey.'],
    example: 'Maya discovers a free BrightPath checklist, asks about a workshop, books a call for her team, and then needs joining instructions. Each interaction calls for a different response: useful information, a clear answer, a sales conversation, and support.',
    steps: ['Choose one offer: a beginner design workshop for creative teams.', 'Write the main question Maya has before finding the offer: How can my team make better designs?', 'List four moments: discover a tip, register interest, discuss team training, get help after booking.', 'Write one helpful action and one responsible team next to each moment.', 'Circle any moment with no owner or unclear next step. Fix the process on paper before thinking about automation.'],
    outcome: 'You have a short journey map with a customer need, a helpful response, and an owner at each step.',
    pitfalls: ['Do not make every interaction a sales pitch.', 'A diagram does not prove that someone has consented or bought anything.'],
    advanced: 'A business may use several journeys for different products and audiences. Use the same clear record definitions so teams can still understand the person across those journeys.',
    recap: ['Start with the person\'s need.', 'Give each important handoff an owner.', 'Use tools to support a process, not to replace thinking about it.'], sources: ['academy', 'objects', 'lifecycle'],
    quiz: [Q('Maya has paid but cannot find joining instructions. What is the most helpful next action?', ['Send the original sales pitch again', 'Delete her record', 'Help her access the workshop'], 2, 'Support the need she has now. A repeated sales pitch does not solve access, and deleting the record loses useful context.'), Q('You draw a customer journey. What has changed inside HubSpot?', ['Nothing automatically; this is a plan', 'Every contact moves to Customer', 'A workflow starts immediately'], 0, 'A journey drawing is a planning aid. Actual record changes and workflow enrollment require configuration or actions inside HubSpot.')],
  }),
  L({
    id: 'safe-account', title: 'Choose a safe place to start', minutes: 12, diagram: 'change',
    objective: 'Start learning without putting a work account or customer information at risk.',
    explanation: ['You can finish this learning site without a HubSpot login. If you also want to follow along in HubSpot, use a training account you are allowed to use, or ask your administrator for an approved practice setup. A work account with real customers is not a playground.', 'A regular free account is not the same as a HubSpot sandbox test account. Sandboxes have their own subscription requirements and behavior. Do not assume every account includes one. If creating a new account, begin on HubSpot\'s official website and follow the current signup prompts; these can vary.', 'Protect your login with a unique password and two-factor authentication where supported. Two-factor authentication adds a second check, such as an authenticator app, after a password. Store recovery codes securely outside the CRM. You never need to enter login details, keys, or tokens into this learning site.'],
    example: 'BrightPath\'s trainee begins in the local contact lab. Later, an administrator confirms a separate practice account and explains which actions are allowed. The trainee does not connect a company inbox or import a customer spreadsheet just to get started.',
    steps: ['Choose the easiest route today: stay in the labs on this site.', 'If you need a real account, open the official setup guide below and confirm whether you may create one or use an existing training account.', 'Check the account name before changing anything. Do not use a production account by accident.', 'For an email-and-password login, review Settings > General > Security and follow HubSpot\'s current two-factor setup instructions if available.', 'Keep recovery information private. Skip inbox connections, real imports, and publishing until your organization approves them.'],
    outcome: 'You know where practice is allowed and have a clear boundary between learning and live work.',
    pitfalls: ['Never paste credentials or recovery codes into lesson notes.', 'Do not call an ordinary free account a sandbox.'],
    advanced: 'Single sign-on and two-factor authentication are different controls. Your organization may manage sign-in through its identity provider. Follow that policy rather than changing account security settings on your own.',
    recap: ['The labs work without an account.', 'Confirm the environment before making changes.', 'Keep account secrets out of this site.'], sources: ['setup', 'security', 'catalog'],
    quiz: [Q('Where can you practice immediately without a HubSpot login?', ['Your employer\'s live database', 'The simulations on this site', 'Someone else\'s account'], 1, 'These labs are local teaching simulations. A live or borrowed account requires permission and can affect real people.'), Q('What does two-factor authentication add?', ['A second verification step', 'A free paid subscription', 'Automatic customer consent'], 0, 'Two-factor authentication helps protect sign-in. It does not upgrade a product or establish permission to send marketing.')],
  }),
  L({
    id: 'navigation', title: 'Find your way around without guessing', minutes: 10, diagram: 'crm',
    objective: 'Know where contacts, marketing tools, automation, and reports usually live.',
    explanation: ['HubSpot groups tools by the job they help you do. CRM includes records such as contacts and deals. Marketing includes tools such as forms and email. Content includes website and landing pages. Automation contains workflows, and Reporting contains reports and dashboards.', 'Some current accounts display tools inside a More menu. Other accounts show the same destinations directly. The CRM index page, which means the page listing records, can also have different layouts. Older screenshots may use Create contact, while the newer table view uses Add contacts > Create new.', 'If you cannot find a button, first check the account, menu, plan, and permissions. Missing controls do not mean you failed. Open the linked official guide for the current navigation. Avoid changing settings just to make your screen resemble a tutorial.'],
    example: 'Maya\'s details are under CRM > Contacts. A workshop signup form is under Marketing > Forms. A workshop landing page is under Content > Landing Pages. These are different tools connected by the same business goal.',
    steps: ['Read the four destinations in the example and say what each is for.', 'If using an approved HubSpot account, open More if it appears, then navigate to CRM > Contacts.', 'Look for the table/board view control and the button for adding or creating a contact. Do not create anything yet.', 'Locate Marketing > Email and Marketing > Forms. If unavailable, record that fact instead of upgrading.', 'Find the settings gear. Use the source guide to look up a setting rather than clicking through unfamiliar controls.'],
    outcome: 'You can name the destination for a contact, form, email, and landing page, even if your account\'s menu layout differs.',
    pitfalls: ['Do not assume every tutorial screenshot matches your rollout.', 'A hidden feature may need a plan or permission, not a browser fix.'],
    advanced: 'Administrators can customize object names and record layouts. A company might call a company an account. Confirm the local naming convention before creating duplicate structures.',
    recap: ['Use the tool\'s purpose to find the right menu.', 'Check More when a destination is missing.', 'The official linked guide is the best reference for current buttons.'], sources: ['records', 'forms', 'email', 'pages'],
    quiz: [Q('Where would you normally look for a workshop registration form?', ['Marketing > Forms', 'A deal amount field', 'Your quiz results'], 0, 'Marketing > Forms is the documented destination, sometimes reached through More. A deal amount and this site\'s quizzes do not manage HubSpot forms.'), Q('Your account lacks a button shown in an old tutorial. What next?', ['Change every setting', 'Assume the lesson is impossible', 'Check current docs, plan, and permissions'], 2, 'Menus, rollout, and access differ. Check the current guide and your access before making unrelated changes.')],
  }),
  L({
    id: 'practice-rules', title: 'Learn safely: drafts, examples, and small steps', minutes: 10, diagram: 'change',
    objective: 'Use a repeatable checklist before trying something in a real account.',
    explanation: ['A draft is unfinished work that you have not deliberately sent or published. It is a good place to learn. But some actions, such as imports, property changes, connecting an inbox, or turning on automation, can affect live records even if you never publish a page.', 'Use fictional data in these labs. The sample email addresses are not a mailing list and do not represent real consent. The checkboxes in a simulation teach decision-making; they do not verify legal permission. Keep real customer data, company secrets, and API tokens out of this site.', 'Before a live action, identify the environment, the affected people, the expected result, the approver, and a recovery plan. Work on a small approved sample first. Exporting data is itself a sensitive action; only do it if authorized, and store any approved backup securely.'],
    example: 'Before changing a workshop-interest field, BrightPath\'s trainee checks that it is a practice property, confirms no live workflows use it, and writes down the current settings. For an email lesson, the trainee keeps the email as a draft rather than scheduling a send.',
    steps: ['Write this five-part check in your notes: account, audience, action, approval, recovery.', 'Apply it to the contact lab: this page, fictional person, edit a field, local practice, reset the lab.', 'Apply it to a real email: approved account, intended recipients, send action, reviewer approval, and no true unsend after delivery.', 'Choose a practice-only name such as TRAINING - Design workshop for draft assets in an approved account.', 'Stop before any real send, public publish, payment, deletion, or automation activation until it has been reviewed.'],
    outcome: 'You can explain why a local simulation is safe and which real-world actions need an extra check.',
    pitfalls: ['Do not assume every action can be undone.', 'Do not import the sample dataset into a live account or mark it as legally consented.'],
    advanced: 'A rollback plan depends on the action. Reverting a setting does not reverse an email that already went out or every side effect of a workflow. Plan the recovery before activation.',
    recap: ['Use drafts and fictional data.', 'Small approved tests are easier to understand.', 'A live send or automation change needs deliberate review.'], sources: ['imports', 'email', 'workflows'],
    quiz: [Q('Which action stays entirely inside this learning site?', ['Sending a campaign from HubSpot', 'Changing a fictional record in the local lab', 'Connecting a company inbox'], 1, 'The local lab changes only its teaching state. Sending and connecting an inbox can have effects outside this site.'), Q('Can turning off a workflow undo an email it already sent?', ['Yes, every recipient loses the email', 'Only if the email was personalized', 'No, completed side effects are not automatically reversed'], 2, 'Stopping a process is not the same as reversing completed actions. A delivered email cannot be recalled simply by turning off its workflow.')],
  }),
  L({
    id: 'first-contact', title: 'Create your first contact record', minutes: 13, diagram: 'crm', lab: 'contact',
    objective: 'Understand a contact record by saving a few useful details.', access: 'Free-account practice',
    accessNote: 'Basic contact records are available across plans. Use our free lab first; real edits require permission in a training account.',
    explanation: ['A contact record is a page of information about one person. Properties are the named fields on that page, such as First name, Email, and City. Activities are things that happened, such as a call or a note. They are useful together but are not the same kind of information.', 'Email is an important identifier for contacts. In common HubSpot creation and import paths, HubSpot uses it to find existing contacts and reduce duplicates. Two people can share a first name, so a name alone is a poor identifier. Always search before adding someone you think may already exist.', 'A contact owner is the team member responsible for that record. Setting an owner helps establish a next step; it does not create marketing consent. Do not mark a practice contact as marketing merely to make it appear more complete. Marketing status can affect billing in eligible accounts.'],
    example: 'Save Maya Patel, maya@cedar.example, London, and Design in the local contact lab. Maya is still a fictional person. The record is useful because each fact has a named field rather than being buried in a sentence.',
    steps: ['Open the contact lab below. It starts with fictional details.', 'Enter Maya as the first name, Patel as the last name, and maya@cedar.example as the example email.', 'Choose London and Design, then save the practice record. Watch the record preview update.', 'If following in an approved training account, go to CRM > Contacts, using More first if needed. In the updated table view choose Add contacts > Create new; older layouts may say Create contact.', 'Enter the approved training details, inspect any required fields, and choose Create. Do not enable marketing status or claim consent for the fictional sample.', 'Open the saved record and check the email and spelling. Use only approved test data if the account prevents example addresses.'],
    outcome: 'The lab shows a contact with the details you saved. In an approved account, the record can be found by its identifying details.',
    pitfalls: ['Do not create a duplicate just because the spelling of a name changed.', 'Do not confuse assigning an owner with assigning permission to email.'],
    advanced: 'Record creation behavior differs by tool. Forms can use browser cookies and other settings; API behavior also has its own rules. Do not generalize one deduplication rule to every ingestion route.',
    recap: ['A contact is one person, with named properties.', 'Search before creating; choose the right identifier.', 'Ownership, marketing status, and consent are separate.'], sources: ['records', 'duplicates', 'marketingContacts'],
    quiz: [Q('Which is usually a better identifier for a contact import?', ['The first name Maya', 'The city London', 'The correctly mapped Email field'], 2, 'Email is a default contact identifier for this import route. First names and cities can be shared by many people and are not unique identifiers.'), Q('You assign a contact owner. What does that tell you?', ['Who is responsible for the record', 'The contact opted in to every email', 'The contact has paid'], 0, 'Ownership identifies a responsible user. Consent and purchases need their own evidence and fields.')],
  }),
  L({
    id: 'properties', title: 'Give each detail the right field', minutes: 14, diagram: 'crm', lab: 'contact',
    objective: 'Choose a sensible property type and avoid creating unnecessary fields.', access: 'Free-account practice',
    accessNote: 'Basic custom properties are available within plan limits. Creating properties requires Edit property settings permission; advanced types have additional requirements.',
    explanation: ['A property is a named place to store one kind of information. First name is text. A workshop date is a date. A headcount is a number. A dropdown lets a person choose from a controlled set of values. Choosing a suitable type makes filters and reports easier later.', 'Look for an existing property before creating a new one. Two fields called Workshop interest and Workshop interests can split the same information across different places. Add a clear description that tells other people what belongs in the field and who keeps it up to date.', 'The label is the readable name. The internal name is the identifier used by integrations and other technical tools. HubSpot does not let you change the property\'s internal name after creation. Changing a field type later can invalidate existing data, so do not treat a production field like a disposable note.'],
    example: 'BrightPath offers Design, Analytics, and Writing workshops. A dropdown called Workshop interest avoids values such as design, Design course, and designing all meaning the same thing. A separate number field makes sense for Team size.',
    steps: ['Write the information you need: Workshop interest.', 'Check whether an existing property already fits. In an approved account, use Settings > Properties and select Contact properties.', 'If creation is authorized, choose Create property, enter TRAINING - Workshop interest, and select a dropdown field type. Use the full editor when you need options.', 'Add the options Design, Analytics, and Writing. Add a description that explains the intended use.', 'Review the object type and internal name before creating. Stay within the account\'s available limits.', 'In the contact lab, choose an interest and inspect the preview. Think about why a dropdown is better than free text for this example.'],
    outcome: 'You can choose text, number, date, or dropdown for a useful detail and explain why that choice helps future reporting.',
    pitfalls: ['Do not create a custom field when the default one already fits.', 'Changing a live property type is not the same as changing a label.'],
    advanced: 'Some fields support validation or unique-value rules, with feature-specific requirements. A required field on a creation form is not a guarantee that every integration will populate it. Check every important data-entry route.',
    recap: ['Choose a type that matches the fact.', 'Reuse existing properties when possible.', 'Document the meaning and treat internal names carefully.'], sources: ['properties'],
    quiz: [Q('You want exactly three workshop-interest choices. Which type helps?', ['A dropdown', 'A long unstructured note', 'A phone field'], 0, 'A dropdown gives consistent choices. Notes allow many spellings, and a phone field does not match workshop interests.'), Q('Before creating a property, what is the best first check?', ['Whether it has a colorful label', 'Whether an existing property already fits', 'Whether every user can become Super Admin'], 1, 'Reuse an appropriate field before adding another. Color does not solve duplicate definitions, and broad administrator access is unnecessary.')],
  }),
  L({
    id: 'associations', title: 'Connect people, companies, and deals', minutes: 12, diagram: 'crm',
    objective: 'Explain associations and connect the right records without duplicating their details.', access: 'Free-account practice',
    accessNote: 'Basic record associations are broadly available. Custom association labels and limits depend on subscription and object type.',
    explanation: ['An association is a connection between two records. It says these records are related. Maya works at Cedar Studio, so her contact can be associated with that company. A team-training deal can be associated with both Maya and Cedar Studio.', 'Associations are two-way: when record A is associated with B, B is also associated with A. An association does not copy every property to the other record, combine the records, or prove a sale happened. It links the context so a person can move between related information.', 'One company can have many contacts, and one contact can participate in more than one deal. Think carefully about which relationship you mean. A primary company association helps identify a main company where supported. Labels can describe roles, but advanced labeling is not required for this beginner exercise.'],
    example: 'Maya and Sam both work at Cedar Studio. Keep two contact records and one company record, then connect them. If Maya asks about two separate workshops, each genuine sales opportunity may be a different deal associated with the same person.',
    steps: ['Draw Maya and Sam as two contacts and Cedar Studio as one company.', 'Draw a connection from each person to Cedar Studio. Do not make a separate copy of the company for each person.', 'Add a Team workshop deal and connect it to the relevant contact and company.', 'In an approved HubSpot account, open a training record and find the associated-record section. Use its add control to select an existing approved training record.', 'Open the other record and inspect the relationship. Confirm you did not merge the records or create an unnecessary duplicate.'],
    outcome: 'You have a relationship map with separate records and clear links. You can explain why connecting is different from merging.',
    pitfalls: ['Do not duplicate the company just to attach another person.', 'An association is not proof of consent or a completed purchase.'],
    advanced: 'Filtering on associated records often means at least one associated record matches, unless you choose a different rule. Later, reports with one-to-many relationships need careful counting to avoid repeated totals.',
    recap: ['Associations link separate records.', 'Relationships can be one-to-many.', 'Linking does not merge or copy every property.'], sources: ['associations', 'objects', 'segments'],
    quiz: [Q('Two people work at Cedar Studio. What is the clean model?', ['One combined contact for both people', 'Two identical companies with no links', 'Two contacts associated with one company'], 2, 'Each person needs their own record, while the shared company can remain one record. This preserves individual history and a common business context.'), Q('What does associating a contact and a deal do?', ['Links their relationship', 'Guarantees the deal is won', 'Copies every deal field into the contact'], 0, 'An association creates a relationship. It does not set the deal outcome or duplicate all properties.')],
  }),
  L({
    id: 'prepare-import', title: 'Prepare a small, clean spreadsheet', minutes: 14, diagram: 'import', lab: 'import',
    objective: 'Prepare data before import so you know what will be created or updated.',
    explanation: ['An import moves structured information from a file into records. A CSV is a text file that represents a table. The first row contains column names, and each following row contains data. For a contact import, each row should represent the person or update you intend to load.', 'Decide whether you are creating new records, updating existing ones, or both. Updating safely needs a correct identifier. Email is a common contact identifier. HubSpot Record ID is useful for exported records you intend to update, and it takes precedence over other identifiers in an import when used.', 'Prepare only the columns you need. Standardize values, check required fields, inspect date and number formats, and remove accidental blank rows. An import checkbox is not a substitute for actual permission to use data. Our fictional CSV is for learning, not a real marketing list.'],
    example: 'The BrightPath sample file contains First name, Last name, Email, City, and Workshop interest. Maya\'s row has one email and one interest. A file with Team size written as ten in one row and 10 in another needs cleanup before a number-field import.',
    steps: ['Open Resources and download the fictional practice CSV.', 'Open it in a spreadsheet app. Check the header row and confirm you understand every column.', 'Check that the email values are distinct. Keep names in their separate columns.', 'Write down the intended action: practice mapping only; do not upload this file to a production account.', 'For a real approved import later, identify the required fields, identifier, create/update mode, and date/number formats before starting.', 'Use the import lab to practice the mapping decision without uploading anything.'],
    outcome: 'You can describe the file\'s row meaning, columns, identifier, and intended operation before an import begins.',
    pitfalls: ['Do not assume a person\'s name is unique.', 'Do not claim fictional or purchased contacts expect to hear from you.'],
    advanced: 'For real updates, an authorized export of existing identifiers may be useful, but exports can contain personal data. Keep any approved backup secure and do not copy it into this public learning project.',
    recap: ['One clear row meaning comes first.', 'Choose an identifier and action before mapping.', 'A clean file is easier to verify than a large uncertain one.'], sources: ['imports', 'duplicates'],
    quiz: [Q('What should you decide before clicking through an import wizard?', ['Whether to create, update, or both', 'Only the file color', 'How many emails to send immediately'], 0, 'The intended operation determines identifiers and overwrite risks. Spreadsheet colors and an immediate email send are not a safe import plan.'), Q('If Record ID is used as an import identifier, what is important?', ['It is the contact\'s first name', 'It overrides other included unique identifiers for matching', 'It proves email consent'], 1, 'HubSpot documents that Record ID takes precedence when used in an import. It is a record identifier, not a name or proof of consent.')],
  }),
  L({
    id: 'map-import', title: 'Match columns to the right properties', minutes: 15, diagram: 'import', lab: 'import',
    objective: 'Map a file carefully and verify the result instead of trusting automatic guesses.', access: 'Free-account practice',
    accessNote: 'Basic imports are available across plans, with Import and object Edit permissions. Use the local mapping lab for fictional data.',
    explanation: ['Mapping means telling HubSpot which property receives each column. A column called Given name should map to First name, not Company name. Automatic suggestions save time, but you still need to check them. Similar names can hide very different meanings.', 'In the documented single-object flow, you can reach imports from Data Management > Data Integration or an object\'s Import control. Advanced imports lets you choose the object and whether to create, update, or both. Quick contact imports use a different flow. Use the current guide for the route you choose.', 'You can skip unnecessary columns and use a Don\'t overwrite option where offered to protect existing values. After an approved import, read the summary and any error report, then inspect representative records. A completed upload is not proof that every row was imported correctly.'],
    example: 'The lab has Given name, Family name, Email address, and City. Correct mappings are First name, Last name, Email, and City. Mapping Email address into a text note would lose its role as the contact identifier.',
    steps: ['Open the import lab. No real file is uploaded there.', 'Match Given name to First name and Family name to Last name.', 'Match Email address to Email and City to City, then check your mapping.', 'In an approved real import only, select the right object and create/update mode before uploading the reviewed file.', 'Review every column, identifier, and overwrite choice. Skip fields you do not understand. Do not complete a required consent attestation unless it is true for the real data.', 'After an authorized import, inspect the created/updated counts, errors, and a few records. Keep the import name and review notes for troubleshooting.'],
    outcome: 'The lab confirms four correct mappings. You know which post-import checks would be needed for an authorized real file.',
    pitfalls: ['An automatic mapping suggestion still needs review.', 'Do not re-import an error file blindly; understand the error and matching rule first.'],
    advanced: 'When updating existing records only, new unmatched rows are ignored rather than created. Empty or wrong identifiers can cause different outcomes in other modes. Test the exact mode with an approved small sample.',
    recap: ['Map meaning, not just similar-looking labels.', 'Review identifiers and overwrite rules.', 'Verify results after the import.'], sources: ['imports'],
    quiz: [Q('Where should Given name map in a contact import?', ['Company domain name', 'First name', 'Deal amount'], 1, 'Given name means the person\'s first name. A company domain and deal amount describe different entities and values.'), Q('The import finishes. What should you do next?', ['Assume every row is perfect', 'Immediately send a campaign', 'Review counts, errors, and sample records'], 2, 'Verification catches ignored rows, failed values, and incorrect mapping. Completion alone does not establish correctness or consent to send.')],
  }),
  L({
    id: 'clean-records', title: 'Keep records tidy without losing history', minutes: 13, diagram: 'import',
    objective: 'Spot duplicates and inconsistent data, then choose a careful next step.',
    explanation: ['Clean data is information that your team can understand and trust. Duplicate records split history. Inconsistent dropdown or text values make groups unreliable. Missing owners leave next steps unclear. Cleaning data is a repeating habit, not just an import-day activity.', 'HubSpot has different deduplication rules for different objects and input routes. Contacts commonly use email; companies commonly use domain names. Record ID and custom unique-value properties can also matter. API-created companies and certain other routes have exceptions, so always check the specific rule.', 'A merge combines records and can be hard or impossible to reverse as you expect. Do not merge two people just because their names look similar. Review identifiers, associations, activities, and ownership. Built-in duplicate-management tools and advanced data-quality features depend on your plan.'],
    example: 'Two Maya Patel records may be the same person with duplicated data, or two different people. BrightPath compares the email, company association, and activity history before making a decision. It does not delete a record merely because City is blank.',
    steps: ['In your notes, list three possible issues: duplicate email, inconsistent workshop interest, and missing owner.', 'For each issue, write how you would confirm it rather than guessing.', 'Use the sample data to compare name-based matching with email-based matching. Notice how names could collide.', 'For a real issue, ask the record owner or administrator to review the identifiers and history before an authorized merge.', 'Standardize a field only after agreeing on its meaning. Recheck any segments or reports that depend on it.'],
    outcome: 'You can distinguish finding a possible issue from safely correcting it.',
    pitfalls: ['Similar names are not sufficient evidence for a merge.', 'Deleting a record is not a harmless way to clean up a report.'],
    advanced: 'A reliable data process defines which system owns each field and how conflicting updates are resolved. Otherwise a cleaned value can be overwritten again by an integration.',
    recap: ['Confirm the identity, not just the name.', 'Check history before merging.', 'Fix the source of repeated data problems.'], sources: ['duplicates', 'properties', 'sync'],
    quiz: [Q('Two records have the same name. What does that prove?', ['They must be the same person', 'Nothing by itself; compare stronger evidence', 'Both should be deleted'], 1, 'Names can be shared. Check identifiers, associations, and history before an approved correction. Duplicate-looking records are not automatic permission to merge or delete.'), Q('A cleaned field keeps reverting after a sync. What should you examine?', ['The integration\'s field mapping and conflict rules', 'Only the page color', 'The quiz score'], 0, 'A connected system may be writing an older value back. Fix the update source and conflict policy rather than repeatedly editing the symptom.')],
  }),
  L({
    id: 'lifecycle-stages', title: 'Know the difference between stages and statuses', minutes: 14, diagram: 'lifecycle',
    objective: 'Separate a person\'s overall relationship from a deal\'s progress.', access: 'Free-account practice',
    accessNote: 'Lifecycle stage properties are broadly available. Automatic updates, calculated time fields, and some customization need specific access.',
    explanation: ['Lifecycle stage describes where a contact or company sits in your marketing and sales process. Default options include Subscriber, Lead, Marketing Qualified Lead, Sales Qualified Lead, Opportunity, Customer, Evangelist, and Other. Your organization can define and customize its process; not every person must visit every stage.', 'MQL means marketing qualified lead: marketing judges the person ready for sales. SQL means sales qualified lead: sales judges the person a potential customer. Lead Status describes sales follow-up detail, such as Attempted to Contact. Deal stage belongs to a particular deal, not to the person\'s entire relationship.', 'Many tools that update the default Lifecycle stage, including imports, forms, APIs, and workflows, normally move it forward. Moving it backward using those tools requires clearing the existing value first. Manual updates and automatic settings have their own effects, including history changes. Do not reset live stages to make a report look better.'],
    example: 'Maya may be a Lead after requesting workshop information. If marketing qualifies her for a team sale, she becomes an MQL under BrightPath\'s agreed rules. A related deal could be in Proposal while Maya\'s lifecycle stage is Opportunity. Those fields describe different things.',
    steps: ['Write three headings: Lifecycle stage, Lead Status, and Deal stage.', 'Place Lead and Customer under Lifecycle stage. Place Attempted to Contact under Lead Status.', 'Place Proposal under Deal stage and label it as an example custom sales stage, not a universal HubSpot default.', 'Use a fictional scenario to decide which field changes when a salesperson makes a call versus when a sale is won.', 'If inspecting a training account, find Lifecycle stage on a training contact and compare it with a related deal\'s stage. Do not bulk change anything.'],
    outcome: 'You can explain which field describes the overall relationship, a follow-up status, or one deal\'s progress.',
    pitfalls: ['A lifecycle stage is not a deal stage.', 'An email open alone is not a universal MQL rule.'],
    advanced: 'Review account-level lifecycle automation before diagnosing a stage change. Association settings, imports, forms, integrations, and workflows can all participate. Use property history to identify the actual source.',
    recap: ['Lifecycle = relationship; deal stage = one sale.', 'MQL and SQL need shared definitions.', 'Know the update rules before changing stage values.'], sources: ['lifecycle'],
    quiz: [Q('Which property describes one possible sale moving toward a decision?', ['City', 'Deal stage', 'Email subscription type'], 1, 'Deal stage tracks a particular opportunity. City describes location, and subscription type concerns communication preferences.'), Q('Can you assume an import will move Customer back to Lead directly?', ['Yes, always', 'Only if you rename the file', 'No; default lifecycle tools normally move forward unless the value is cleared first'], 2, 'HubSpot documents forward-only behavior for several tools updating the default lifecycle property. Plan and authorize any backward change carefully; file naming does not alter that rule.')],
  }),
  L({
    id: 'qualification', title: 'Decide what a good-fit lead means', minutes: 12, diagram: 'lifecycle',
    objective: 'Write a simple qualification rule that your marketing and sales teams can agree on.',
    explanation: ['Qualification means deciding whether a person or company is a sensible next conversation. Fit is how well their needs match your offer. Engagement is what they have done, such as requesting information. A large score is not a substitute for understanding either.', 'Agree on the conditions before changing lifecycle stages. For a team workshop, useful signals might include a relevant need and an explicit request to discuss team training. These are example business rules, not HubSpot defaults. A newsletter signup may simply mean the person wants a newsletter.', 'Use only appropriate data and avoid assumptions based on sensitive traits. Treat weak signals carefully: open tracking can be affected by image loading and privacy features, and not every click is a person expressing buying intent. Review outcomes and revise the rule with your sales team.'],
    example: 'BrightPath\'s example MQL rule is a team-training request with a suitable workshop interest and enough information for an owner to respond. A person who only reads a blog post is not automatically sent to sales as a qualified lead.',
    steps: ['Write one sentence describing the ideal customer need for a team workshop.', 'Choose two observable signals: a matching need and a request for a conversation.', 'Write what does not qualify yet, such as a newsletter signup without a team-training request.', 'Apply the rule to three fictional examples: Maya requests team training, Leo asks for a free tip, and Nia has no clear need yet.', 'Ask how sales would accept, return, or reject the lead. Record the reason so the rule can improve.'],
    outcome: 'You have a plain-English qualification rule and can explain why each sample fits or does not fit.',
    pitfalls: ['Do not present your example scoring threshold as a HubSpot default.', 'Do not promote every email opener to a sales-ready stage.'],
    advanced: 'Lead-scoring features vary by subscription. Before using one, define the inputs, limits, decay behavior where applicable, and how you will validate the score against actual outcomes.',
    recap: ['Separate fit from engagement.', 'Agree on definitions before automating.', 'Use evidence and feedback rather than arbitrary numbers.'], sources: ['lifecycle', 'emailMetrics', 'catalog'],
    quiz: [Q('Which is strongest evidence of interest in a team workshop?', ['An explicit request to discuss team training', 'One tracked email open', 'A missing city field'], 0, 'A direct request is clearer intent than a weak tracking event. Missing data tells you little about interest.'), Q('Who should help define a marketing-to-sales qualification rule?', ['Only whoever clicks fastest', 'Marketing and sales together', 'Nobody; every account has the same rule'], 1, 'A shared definition makes the handoff useful. HubSpot provides tools and stages, but the business must agree what qualifies for its offer.')],
  }),
  L({
    id: 'handoff', title: 'Hand a lead over without dropping the context', minutes: 12, diagram: 'sales',
    objective: 'Create a clear handoff with an owner, a reason, and a next step.',
    explanation: ['A handoff is the moment one team passes responsibility to another. Sending an alert is not enough if nobody knows what to do. Include who owns the next action, why this person is ready, what was promised, and when the team should respond.', 'A service-level agreement, often shortened to SLA, is a shared response expectation. Here it means an example team agreement, not a guarantee or a built-in timer you get automatically. A team can start with a manual checklist and only automate it after the process works.', 'Keep context in the right place. A note can describe the customer\'s request. An owner identifies responsibility. A task can capture the next action and due date. Lifecycle and deal fields describe stages. Avoid copying personal data into unnecessary channels just to make the alert detailed.'],
    example: 'Maya asks for a team workshop next month. BrightPath\'s handoff says: owner Jordan, request for six designers, asked for dates and format, next step is a short discovery call, respond within the team\'s agreed working-day window.',
    steps: ['Write a handoff note for Maya with four parts: request, evidence, promise, and next action.', 'Choose a fictional owner and a realistic response expectation.', 'Decide where the sales team will record accepted, needs more information, or not a fit.', 'Test the handoff with a fictional record. Could a teammate act without asking you to repeat the whole story?', 'Only after the manual process is clear, consider a workflow that assigns a task or notifies the owner in an approved account.'],
    outcome: 'A teammate can understand why the lead was handed over and what action to take next.',
    pitfalls: ['An alert with no owner does not create accountability.', 'Do not promise a response time the team cannot meet.'],
    advanced: 'Measure time to first meaningful response, not simply whether an automated notification fired. A workflow log proves a system action, not that the customer received useful help.',
    recap: ['Include owner, reason, promise, and next action.', 'Agree on response expectations.', 'Test the manual handoff before automating it.'], sources: ['lifecycle', 'workflows', 'permissions'],
    quiz: [Q('What is missing from “New lead, please follow up” to an entire team?', ['A brighter background', 'A clear owner and specific next action', 'More copied personal data'], 1, 'A clear owner and action make the handoff usable. Styling and copying more data do not fix unclear responsibility.'), Q('A workflow notification succeeded. What does that prove?', ['The system completed the notification action', 'The customer bought', 'A salesperson had a useful conversation'], 0, 'The log records a system action. It does not prove a human response, a conversation, or a sale.')],
  }),
  L({
    id: 'active-static', title: 'Build a group that fits the job', minutes: 12, diagram: 'segments', lab: 'segments',
    objective: 'Choose between an automatically updated audience and a saved snapshot.', access: 'Free-account practice',
    accessNote: 'Segments are available across plans, with limits and filters depending on access. Creating them requires Edit Segment permission.',
    explanation: ['A segment is a group of records. Older HubSpot tutorials call these lists. An active segment updates membership as records meet or stop meeting its criteria. A static segment is a saved group that does not automatically keep matching its original filters.', 'Use an active segment when the rule should stay current, such as people interested in Design. Use a static segment for a fixed reviewed group, such as a particular event attendance snapshot. Static does not mean unchangeable: records can still be added or removed through supported actions.', 'Segment membership and email eligibility are different. A segment can contain someone who must not receive a particular marketing email. You will need separate checks for subscription preference, applicable consent, marketing status where relevant, and delivery suppressions.'],
    example: 'BrightPath\'s Design interest active segment changes when Maya changes her interest. Its September workshop attendance static segment stays a snapshot unless someone deliberately edits membership. Neither group alone proves anyone may receive marketing.',
    steps: ['Decide whether your goal is a living audience or a historical snapshot.', 'Use the segment lab to choose Design as an interest and inspect the matching people.', 'Switch between active mode and a saved static snapshot, then change the filters. Notice which membership stays fixed.', 'For an approved real segment, go to CRM > Segments, choose Create segment > Manually, and select Contacts.', 'Add the reviewed filters, inspect matching records, then choose Next and select Active or Static. Give it a meaningful name and use Save and process segment.', 'Wait for processing and check the final membership instead of trusting an early preview count.'],
    outcome: 'You can explain why a changing newsletter audience and a fixed attendance snapshot need different segment behavior.',
    pitfalls: ['A static segment does not continually re-evaluate its filters.', 'A segment is not a record of legal consent by itself.'],
    advanced: 'An active segment reflects current rules, so historical reports based on its current membership can change as records change. For a historical analysis, state whether you need today\'s audience or a snapshot from that time.',
    recap: ['Active updates with criteria.', 'Static is a snapshot that can still be edited deliberately.', 'Audience selection and send eligibility are separate.'], sources: ['segments', 'email'],
    quiz: [Q('Which group should keep updating when Workshop interest changes?', ['An active segment', 'A static attendance snapshot', 'A screenshot'], 0, 'An active segment re-evaluates its rules. A static segment does not automatically keep matching the original criteria, and a screenshot is not a live group.'), Q('What are lists called in the current documentation?', ['Tickets', 'Segments', 'Seats'], 1, 'The current guide calls them segments and notes the previous name lists. Tickets track help requests, while seats are user access assignments.')],
  }),
  L({
    id: 'and-or', title: 'AND and OR, without the headache', minutes: 13, diagram: 'segments', lab: 'segments',
    objective: 'Read audience rules clearly and predict which sample people will match.', access: 'Free-account practice',
    accessNote: 'Practice all of the logic in this lab for free. Specific HubSpot filters and associated-object options depend on the account.',
    explanation: ['AND means every condition must be true. OR means at least one condition must be true. Design AND London is narrower than Design OR London, when applied to the same two conditions. Read the rule aloud before using it.', 'Groups control how conditions fit together. “Design OR Analytics, AND subscribed” should mean that subscription is required for either interest. If you accidentally write “Design OR (Analytics AND subscribed),” people interested in Design can match without the subscription condition. Parentheses make the intended logic easier to see.', 'Unknown values need attention too. A blank city does not tell you where a person lives. Do not quietly interpret unknown as a confirmed no. HubSpot filter operators and associated-object rules have specific behavior; inspect sample matching and nonmatching records rather than only checking totals.'],
    example: 'Maya is in London and likes Design. Sam likes Design but lives in Delhi. Leo lives in London and likes Analytics. Design AND London matches Maya. Design OR London matches all three. A separate subscribed-only check must still be satisfied for a safe training email audience.',
    steps: ['Open the audience lab and choose Design for interest and London for city.', 'Set the connector to AND. Read the result names, not just the count.', 'Switch to OR and explain which extra people appear and why.', 'Turn the subscribed-only exclusion on. Observe that it applies after the interest/city rule in both modes.', 'Return to AND and keep subscribed-only on. Check the target challenge: Maya should be the only match.', 'In HubSpot, use the segment\'s Test matches control where available and inspect individual records before saving.'],
    outcome: 'You can predict AND versus OR results and keep required exclusions outside an optional branch.',
    pitfalls: ['OR usually broadens the audience; it is not another spelling of AND.', 'A correct count can still contain the wrong people.'],
    advanced: 'Filters on associations can mean any associated record or all associated records, depending on the operator you choose. If two conditions refer to related deals, verify whether they must match the same deal.',
    recap: ['AND requires every condition; OR requires at least one.', 'Group the rule before applying it.', 'Inspect real matches and known nonmatches.'], sources: ['segments'],
    quiz: [Q('Maya matches Design and London. Leo matches London only. Who matches Design AND London?', ['Both', 'Leo only', 'Maya only'], 2, 'AND requires both conditions. Maya meets both, while Leo only meets the location condition.'), Q('What is the clearest rule if subscription is always required?', ['(Design OR Analytics) AND subscribed', 'Design OR (Analytics AND subscribed)', 'Subscribed is optional when interest is known'], 0, 'The first rule applies subscription to either interest. The second allows Design contacts through without that check, and knowing an interest is not permission to ignore subscription preferences.')],
  }),
  L({
    id: 'audience-safety', title: 'The right audience is more than a filter', minutes: 14, diagram: 'segments',
    objective: 'Separate audience fit, marketing status, subscription preference, and delivery checks.',
    explanation: ['A relevant audience is only the first check. Subscription type describes what kind of communication a person has chosen to receive. Marketing contact status is a separate product and billing classification in eligible accounts. A contact can be marked marketing and still have opted out of the email type you want to send.', 'Marketing status does not manufacture consent. Respect opt-outs, applicable laws, your organization\'s policy, and HubSpot\'s sending requirements. A purchased address or a record created by a colleague is not a shortcut around those rules. Use the current subscription documentation and involve your privacy team for real decisions.', 'Also review delivery suppressions such as hard bounces and engagement safeguards. In the current email editor, individual recipient selections and segment exclusions have documented precedence rules. Do not assume adding an exclusion segment overrides every manually included individual. Review the actual recipient preview and reasons before a real send.'],
    example: 'Noah likes Design and lives in London but is unsubscribed. He may match a broad interest segment, but BrightPath should not send him the workshop newsletter. A separate sample with a hard bounce needs a different diagnosis; it is not fixed by changing the subject line.',
    steps: ['Create a four-part checklist: relevance, permission/preferences, marketing status when applicable, and delivery eligibility.', 'Use the audience lab to see Noah disappear when subscribed-only is enabled. Remember this is a simplified training rule.', 'For a real draft email, confirm its subscription type and review Send to and Don\'t send to selections.', 'Inspect individually added recipients as well as segments. Use Audience > Review reasons where available to understand exclusions.', 'Keep the email in draft until the audience has been reviewed and approved. Never use a status change to bypass an opt-out.'],
    outcome: 'You can explain why “in the segment” and “allowed to receive this email” are not the same claim.',
    pitfalls: ['Marketing contact status is not legal consent.', 'Do not remove safeguards just to increase the recipient count.'],
    advanced: 'Changing from non-marketing to marketing can affect billing, and changing back may follow account update-date rules. Check the live catalog and billing documentation before a real bulk status update.',
    recap: ['Treat fit, consent, status, and delivery as separate checks.', 'Review final recipients and exclusion reasons.', 'Do not override opt-outs to solve a send-count problem.'], sources: ['marketingContacts', 'subscriptions', 'email', 'catalog'],
    quiz: [Q('A contact is marked Marketing but has opted out of your newsletter. What should you do?', ['Send because Marketing overrides the opt-out', 'Respect the opt-out', 'Rename the newsletter to bypass it'], 1, 'Marketing is not consent. Respect the communication preference and applicable rules; renaming or changing status is not a legitimate workaround.'), Q('A segment contains 100 people. Does that guarantee 100 deliveries?', ['No; eligibility and delivery checks still apply', 'Yes, segments guarantee delivery', 'Only if you use OR'], 0, 'Preferences, status, suppressions, and delivery results can reduce the number. AND/OR chooses membership, not guaranteed delivery.')],
  }),
];